import Foundation
@testable import KairosKit

/// Loads protocol/test-vectors.json (generated by the Node reference implementation) as plain JSON.
struct Vectors {
    let root: [String: Any]

    static func load(file: StaticString = #filePath) throws -> Vectors {
        // .../apps/ios/KairosKit/Tests/KairosKitTests/Vectors.swift -> repo root
        var url = URL(fileURLWithPath: "\(file)")
        for _ in 0 ..< 6 { url.deleteLastPathComponent() }
        let data = try Data(contentsOf: url.appendingPathComponent("protocol/test-vectors.json"))
        return Vectors(root: try JSONSerialization.jsonObject(with: data) as! [String: Any])
    }

    func list(_ key: String) -> [[String: Any]] { root[key] as! [[String: Any]] }
    var auth: [String: Any] { root["auth"] as! [String: Any] }
}

extension Dictionary where Key == String, Value == Any {
    func str(_ key: String) -> String { self[key] as! String }
    func strs(_ key: String) -> [String] { self[key] as! [String] }
    func int(_ key: String) -> Int { (self[key] as! NSNumber).intValue }
    func u64(_ key: String) -> UInt64 { (self[key] as! NSNumber).uint64Value }
    func bool(_ key: String) -> Bool { (self[key] as! NSNumber).boolValue }
    func obj(_ key: String) -> [String: Any] { self[key] as! [String: Any] }
    func array(_ key: String) -> [[String: Any]] { self[key] as! [[String: Any]] }
    /// A number, or nil for JSON null.
    func optInt(_ key: String) -> Int? { (self[key] as? NSNumber)?.intValue }
    func optStr(_ key: String) -> String? { self[key] as? String }
    func hexData(_ key: String) -> Data { Data(hex: str(key))! }
}

extension Data {
    init?(hex: String) {
        guard hex.count % 2 == 0 else { return nil }
        var bytes = [UInt8]()
        var index = hex.startIndex
        while index < hex.endIndex {
            let next = hex.index(index, offsetBy: 2)
            guard let byte = UInt8(hex[index ..< next], radix: 16) else { return nil }
            bytes.append(byte)
            index = next
        }
        self.init(bytes)
    }

    var hex: String { map { String(format: "%02x", $0) }.joined() }
}

/// The wire config of a vector, as the app's model.
func configFrom(_ j: [String: Any]) -> CameraConfig {
    CameraConfig(
        name: (j.str("name")).isEmpty ? nil : j.str("name"),
        cameraType: j.str("cameraType"),
        wakeUpTimeout: Double(j.int("wakeUpTimeout")),
        startBefore: Double(j.int("startBefore")),
        endAfter: Double(j.int("endAfter")),
        zcam: .init(cameraIp: j.optStr("cameraIp")),
        attempts: j.array("attempts").map { .init(name: $0.str("name"), seconds: UInt32($0.int("time"))) }
    )
}
